    local XMusicPlayerEnum = XMVCA.XMusicPlayer.Enum
    local cdControl = self._Control:GetCDPlayerControl()
    local useStatus = cdControl:GetMusicUseStatusAndConditionDesc(musicID)
    local isUnLock    = useStatus == XMusicPlayerEnum.MusicUseStatus.unlock

    self:_RefreshLimitTime()
    self.TxtSelectLock.gameObject:SetActive(isUnLock)
    if self.GoEgg then 
        self.GoEgg.gameObject:SetActive(cdControl:NeedShowEggTag(musicID))
    end

    local musicListControl = self._Control:GetMusicmusicListControl()
    local isFavorite = musicListControl:CheckMusicIsInListByListType(XMusicPlayerEnum.MusicListType.Favorite,musicID)
    local isBGM = musicListControl:CheckMusicIsInListByListType(XMusicPlayerEnum.MusicListType.BGM,musicID)

    XMVCA.XMusicPlayer.Util.SetBtnStatusPro(self.BtnLike, isFavorite and CS.UiButtonState.Select or CS.UiButtonState.Normal)
    XMVCA.XMusicPlayer.Util.SetBtnStatusPro(self.BtnBgm, isBGM and CS.UiButtonState.Select or CS.UiButtonState.Normal)

    local _, listType = self:_GetMusicListViewStatusAndType()
    local isCurPlay = cdControl:GetCurMusicListType() == listType
            and cdControl:GetCurPlayingMusicID() == self._MusicID

    self.GOSelectedBg.gameObject:SetActive(false)
    self.GoAlbumNotSelect.gameObject:SetActive(false)
    self.GoAlbumSelect.gameObject:SetActive(false)
    self.GoAlbumSelectLock.gameObject:SetActive(false)
    self.ImgNoSelectBg.gameObject:SetActive(not isCurPlay)
    if isUnLock then
        self.GoAlbumSelectLock.gameObject:SetActive(true)
    elseif isCurPlay then
        self.GOSelectedBg.gameObject:SetActive(true)
        self.GoAlbumSelect.gameObject:SetActive(true)
