    self.BtnBgm.gameObject:SetActive(false)
    self.BtnUp.gameObject:SetActive(false)
    self.BtnDown.gameObject:SetActive(false)
    if not isUnLock then
        if status == XMusicPlayerEnum.MusicListUIStatus.manager then
        self.BtnLike.gameObject:SetActive(true)
        self.BtnBgm.gameObject:SetActive(true)
        if listType == XMusicPlayerEnum.MusicListType.BGM then
