function XUiMusicPlayerMusicListCellView:_RefreshLimitTime()
    if not XTool.IsNumberValid(self._MusicID) then
        return
    end
    local XMusicPlayerEnum = XMVCA.XMusicPlayer.Enum
    local musicCO = self._MusicPlayerConfig:GetMusicPlayerAlbumCOByid(self._MusicID)
    local useStatus = self._Control:GetCDPlayerControl():GetMusicUseStatusAndConditionDesc(self._MusicID)

    if useStatus == XMusicPlayerEnum.MusicUseStatus.limitedFree then
        self.GoLimitInfo.gameObject:SetActive(true)
        self.TxtLimitedTime.text = self._Control:GetCDPlayerControl():GetTimeIdLeftStr(musicCO.ExperienceTimeId)
    else
        self.GoLimitInfo.gameObject:SetActive(false)
    end
end

